def transform(grid):
    from collections import Counter
    g = np.array(grid)
    H, W = g.shape
    inb = lambda y, x: 0 <= y < H and 0 <= x < W

    # 1. find the T markers (bar of three 1's + stem cell); the centre may be another colour
    ts = []
    for y in range(H):
        for x in range(W):
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                py, px = dx, dy
                bar = [(y + py, x + px), (y - py, x - px)]
                stem = (y + dy, x + dx)
                back = (y - dy, x - dx)
                if not all(inb(*c) for c in bar + [stem]):
                    continue
                if not (all(g[c] == 1 for c in bar) and g[stem] == 1):
                    continue
                if inb(*back) and g[back] == 1:
                    continue
                corners = [(y + dy + py, x + dx + px), (y + dy - py, x + dx - px)]
                if not all(inb(*c) for c in corners) or any(g[c] == 1 for c in corners):
                    continue
                owner = int(g[corners[0]])
                paint = int(g[y, x]) if g[y, x] != 1 else owner
                ts.append(dict(cells=bar + [stem, (y, x)], owner=owner, paint=paint,
                               target=(y + 2 * dy, x + 2 * dx)))

    # 2. find the L marker (5-cell corner in a 3x3 box) -> rotation direction
    lcells, orient = None, None
    for o in objects(g):
        if o["colour"] == 1 or o["size"] != 5:
            continue
        y0, x0, y1, x1 = o["box"]
        if y1 - y0 != 2 or x1 - x0 != 2:
            continue
        s = set(o["cells"])
        for cy in (y0, y1):
            for cx in (x0, x1):
                if all((cy, xx) in s for xx in range(x0, x1 + 1)) and all((yy, cx) in s for yy in range(y0, y1 + 1)):
                    lcells, orient = s, ('T' if cy == y0 else 'B') + ('L' if cx == x0 else 'R')
        if lcells:
            break

    # 3. erase the markers back to the surrounding region colour
    c = g.copy()
    for t in ts:
        for cl in t["cells"]:
            c[cl] = t["owner"]
    if lcells:
        cnt = Counter()
        for (y, x) in lcells:
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    yy, xx = y + dy, x + dx
                    if inb(yy, xx) and (yy, xx) not in lcells:
                        cnt[int(c[yy, xx])] += 1
        for cl in lcells:
            c[cl] = cnt.most_common(1)[0][0]
    emit(c, "Erase every T marker and the L marker, replacing them with the colour of the region they sit in")

    # 4. each T paints the region its stem points into (regions taken from the erased canvas)
    out = c.copy()
    for t in ts:
        ty, tx = t["target"]
        if not inb(ty, tx):
            continue
        for comp in components(c == c[ty, tx]):
            if (ty, tx) in comp:
                for cl in comp:
                    out[cl] = t["paint"]
                break
        emit(out, f"T in colour-{t['owner']} region points into the region at {t['target']}: paint it {t['paint']}")

    # 5. rotate according to the L marker's orientation
    k = {'TR': 1, 'TL': -1, 'BL': 1, 'BR': -1}.get(orient, 0)
    if k:
        out = np.rot90(out, k)
        emit(out, "L marker present: rotate the whole grid " + ("counter-clockwise" if k == 1 else "clockwise"))
    else:
        emit(out, "No L marker: keep the orientation")
    return out
